library(ggplot2)
navy<-'#183447';blue<-'#216F8F';orange<-'#D8753B'
theme_set(theme_minimal(base_size=14)+theme(plot.title=element_text(face='bold',size=21,color=navy),plot.subtitle=element_text(size=12,color=navy,margin=margin(b=14)),plot.caption=element_text(size=10,hjust=0,color='#536975',margin=margin(t=14)),plot.title.position='plot',panel.grid.minor=element_blank(),legend.position='top',legend.title=element_blank(),plot.margin=margin(18,24,18,18),axis.title=element_text(size=12)))
save_fig<-function(p,name,h=6.5){ggsave(paste0('figures/',name,'.png'),p,width=11,height=h,dpi=170,bg='white');ggsave(paste0('figures/',name,'.pdf'),p,width=11,height=h,device=cairo_pdf)}
p<-analysis$primary;p$word<-factor(p$word,levels=c('i','you','we','not','love'));p$scope<-factor(p$scope,levels=c('all','at_least_30s'),labels=c('All known records','Records lasting ≥30 seconds'))
f1<-ggplot(p,aes(word,100*proportion,color=weighting))+geom_point(position=position_dodge(.4),size=3.6)+facet_wrap(~scope)+scale_color_manual(values=c(blue,orange))+labs(title='The same titles, two different language profiles',subtitle='“You” leads across distinct titles. “I” leads when repeated listening counts.',x=NULL,y='Word presence (%)',caption='Each word counted once per exact artist/title pair. Denominators are rebuilt for the ≥30-second sensitivity.');save_fig(f1,'01_word_weighting')
s<-analysis$salience;z<-dplyr::bind_rows(head(s,9),tail(s,9));z$word<-reorder(z$word,z$log2_ratio)
f2<-ggplot(z,aes(log2_ratio,word))+geom_vline(xintercept=0,color='#B0BEC5')+geom_segment(aes(x=0,xend=log2_ratio,yend=word),color='#B0CBD7',linewidth=1)+geom_point(aes(size=title_pairs,color=log2_ratio>0))+scale_color_manual(values=c(blue,orange),guide='none')+labs(title='Repetition amplifies some words more than others',subtitle='Nine highest and nine lowest descriptive salience scores; minimum 20 distinct pairs.',x='Log₂(record presence / pair presence), smoothed',y=NULL,size='Distinct pairs',caption='A score of +1 means roughly twice the record-weighted prevalence; −1 means roughly half.\nThis ranking is descriptive, not a significance test or a claim about meaning.');save_fig(f2,'02_salience',8)
c<-analysis$annotation$comparison;c<-c[is.finite(c$log2_ratio_change),];c<-head(c[order(abs(c$log2_ratio_change),decreasing=TRUE),],12);c$word<-reorder(c$word,c$log2_ratio_change)
f3<-ggplot(c,aes(log2_ratio_change,word))+geom_vline(xintercept=0,color='#B0BEC5')+geom_segment(aes(x=0,xend=log2_ratio_change,yend=word),color='#B0CBD7',linewidth=1)+geom_point(color=orange,size=3)+labs(title='How much is the title carrying release metadata?',subtitle='Largest salience shifts after conservative trailing live/remaster suffix removal.',x='Change in log₂ salience: suffix removed − full title',y=NULL,caption='1,458 pairs / 8,030 records change. Original pair identities and denominators stay fixed.\nOnly words meeting the reporting threshold in both conditions appear here.');save_fig(f3,'03_suffix_sensitivity',7)
d<-analysis$diversity;d<-d[d$month>'2025-11'&d$month<'2026-11',];d$date<-as.Date(paste0(d$month,'-01'))
f4<-ggplot(d,aes(date,expected_pairs))+geom_hline(yintercept=500,linetype=2,color='#8999A3')+geom_line(color=blue,linewidth=1)+geom_point(color=orange,size=3)+geom_text(data=d[c(1,nrow(d)),],aes(label=sprintf('%.1f',expected_pairs)),vjust=1.8,size=4)+scale_x_date(date_breaks='2 months',date_labels='%b %Y')+coord_cartesian(ylim=c(340,510))+labs(title='More distinct titles at the same listening volume',subtitle='Expected distinct artist/title pairs in a sample of 500 listening records.',x=NULL,y='Expected distinct pairs / 500 records',caption='Exact without-replacement rarefaction; no records discarded. Dashed line is the maximum of 500.\nPartial November boundary months excluded. The vertical axis is intentionally zoomed.');save_fig(f4,'04_rarefaction')
f5<-ggplot(d,aes(date,artist_effective_number))+geom_line(color=blue,linewidth=1)+geom_point(color=orange,size=3)+geom_text(data=d[c(1,nrow(d)),],aes(label=sprintf('%.1f',artist_effective_number)),vjust=-.9,size=4)+scale_x_date(date_breaks='2 months',date_labels='%b %Y')+scale_y_continuous(limits=c(0,NA),expand=expansion(mult=c(.02,.13)))+labs(title='Artist diversity includes evenness, not just a count',subtitle='Shannon effective number: the equivalent number of equally frequent artists.',x=NULL,y='Effective number of artists',caption='Record-weighted artist frequencies. Higher values reflect richness and/or more even listening.\nPartial November boundary months excluded; no claim about why the profile changed.');save_fig(f5,'05_artist_diversity')
j<-analysis$drift$comparisons;j<-j[j$include_comparison,];j$date<-as.Date(paste0(j$month,'-01'));long<-tidyr::pivot_longer(j,c(vocabulary_jsd,pair_composition_jsd,artist_composition_jsd),names_to='measure',values_to='value');long$measure<-factor(long$measure,levels=c('vocabulary_jsd','artist_composition_jsd','pair_composition_jsd'),labels=c('Title vocabulary','Artist composition','Title-pair composition'))
f6<-ggplot(long,aes(date,value,color=measure))+geom_line(linewidth=.9)+geom_point(size=2.7)+scale_color_manual(values=c(blue,orange,'#6C8271'))+scale_x_date(date_breaks='2 months',date_labels='%b %Y')+scale_y_continuous(limits=c(0,1))+labs(title='The repertoire can change faster than its vocabulary',subtitle='Each point compares its labeled month with the preceding month.',x=NULL,y='Jensen–Shannon divergence (base 2)',caption='Fixed retrospective vocabulary: 1,273 words. Partial boundary-month comparisons excluded.\nThe three category spaces differ: absolute magnitudes are not directly equivalent.');save_fig(f6,'06_monthly_drift')
message('Six publication figures saved as PNG and PDF.')
